function pickSea(x,y){if(!pickingReady)return null;uploadWaves();gl.bindFramebuffer(gl.FRAMEBUFFER,pickFramebuffer);gl.viewport(0,0,1,1);gl.uniform2f(uniforms.uPickUV,x/w*2-1,1-y/h*2);gl.uniform4f(uniforms.uWaveMeta,state.waveHeight,waveClock,cameraHeight(),1);gl.disable(gl.DITHER);gl.drawArrays(gl.TRIANGLES,0,6);gl.readPixels(0,0,1,1,gl.RGBA,gl.UNSIGNED_BYTE,pickPixel);gl.enable(gl.DITHER);gl.bindFramebuffer(gl.FRAMEBUFFER,null);gl.viewport(0,0,canvas.width,canvas.height);gl.uniform4f(uniforms.uWaveMeta,state.waveHeight,waveClock,cameraHeight(),0);if(pickPixel.every(v=>v===255))return null;const point={x:(pickPixel[0]/255+pickPixel[1]/65025)*1024-512,z:(pickPixel[2]/255+pickPixel[3]/65025)*1024-512+sceneTime*.14};const ray=OceanWaves.ray(x,y,w,h,sceneTime,state.reduced,cameraHeight());const t=(point.z-ray.origin.z)/ray.direction.z;point.y=ray.origin.y+ray.direction.y*t;if(t<0||t>250)return null;return point;}
function cancelGesture(){if(gesture){const id=gesture.id;gesture=null;try{if(canvas.hasPointerCapture(id))canvas.releasePointerCapture(id);}catch{}}$('gestureGuide').hidden=true;canvas.classList.remove('dragging');}
const touches=new Set();
