canvas.addEventListener('pointermove',e=>{if(!gesture||gesture.id!==e.pointerId)return;e.preventDefault();gesture.lastX=e.clientX;gesture.lastY=e.clientY;const dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;$('gestureGuide').style.width=Math.min(220,Math.hypot(dx,dy))+'px';$('gestureGuide').style.transform='rotate('+Math.atan2(dy,dx)+'rad)';});
canvas.addEventListener('pointerup',e=>{if(!gesture||gesture.id!==e.pointerId)return;const g=gesture;const target=document.elementFromPoint(e.clientX,e.clientY);const blocked=target&&target.closest&&target.closest('button,input,select,nav,.panel,a');if(!blocked&&!state.paused){const q=OceanWaves.fromGesture(g,e.clientX,e.clientY,e.timeStamp,w,h,state.reduced,waveClock);if(q){waves.push(q);if(waves.length>4)waves.shift();canvas.dataset.lastWaveDirection=q.dx.toFixed(3)+','+q.dz.toFixed(3);canvas.dataset.lastWaveStrength=q.amplitude.toFixed(2);$('waveHint').classList.add('quiet');$('waveAnnouncement').textContent='已掀起一道浪，正在沿滑动方向传播';}}cancelGesture();});
for(const type of ['pointercancel','lostpointercapture'])canvas.addEventListener(type,e=>{if(gesture&&gesture.id===e.pointerId)cancelGesture();});
